PROMPT == EXECUTE IN THE CORRECT SCHEMA ==

PROMPT

SET DEFINE ON;

accept SLD_DBN0_T CHAR DEF 'DBN0_T' PROMPT 'Insert Data tablespace name (default: DBN0_T): ';
accept SLD_DBN0_I CHAR DEF 'DBN0_I' PROMPT 'Insert Index tablespace name (default: DBN0_I): ';

COLUMN pnameday NEW_VALUE PARTITION_NAME_DAY
SELECT 'P_'||TO_CHAR(SYSDATE,'YYYYMMDD') as pnameday from dual;
COLUMN pvalueday NEW_VALUE PARTITION_VALUE_DAY
SELECT (''||TO_CHAR(SYSDATE+1,'YYYY-MM-DD')||' 00:00:00') as pvalueday from dual;
COLUMN pnamenextday NEW_VALUE PARTITION_NAME_NEXTDAY
SELECT 'P_'||TO_CHAR(SYSDATE+1,'YYYYMMDD') as pnamenextday from dual;
COLUMN pvaluenextday NEW_VALUE PARTITION_VALUE_NEXTDAY
SELECT (''||TO_CHAR(SYSDATE+2,'YYYY-MM-DD')||' 00:00:00') as pvaluenextday from dual;

